-- fix-2: adds the D&D Beyond details (skills, actions, spells, weapons, speeds) to each character.
-- Safe to run more than once. It only sets the `dnd` field; HP, gold, gear and everything players changed stay as they are.

update public.docs set data = data || $dnd${"dnd": {"pb": 4, "skills": {"acrobatics": 1, "animal-handling": 0, "arcana": 0, "athletics": 1, "deception": 0, "history": 0, "insight": 1, "intimidation": 1, "investigation": 1, "medicine": 0, "nature": 0, "perception": 0, "performance": 1, "persuasion": 0, "religion": 0, "sleight-of-hand": 1, "stealth": 1, "survival": 0}, "adv": [], "half": false, "profs": ["Brewer's Supplies", "Simple Weapons", "Scimitar", "Shortsword", "Crossbow, Hand"], "langs": ["Common", "Common Sign Language", "Elvish"], "senses": [], "speed": {"walk": 30, "bonus": 20}, "acts": [{"n": "Unarmed Strike", "t": "action", "u": 0, "r": "", "d": "Melee attack against a target within 5 ft: damage, grapple, or shove. Martial Arts lets you use Dex instead of Str."}, {"n": "Unarmed Strike (Martial Arts)", "t": "bonus", "u": 0, "r": "", "d": "After you take the Attack action, make one Unarmed Strike as a Bonus Action. Melee attack: Dex mod + prof; hit: Martial Arts die + Dex mod Bludgeoning (or Force). Grapple or Shove DC is your Dex save DC."}, {"n": "Focus Points", "t": "other", "u": 11, "r": "SR", "d": "Spend Focus Points to fuel Monk features. You have one per Monk level and regain them all on a Short or Long Rest."}, {"n": "Flurry of Blows", "t": "bonus", "u": 0, "r": "", "d": "Expend 1 Focus Point to make two Unarmed Strikes as a Bonus Action."}, {"n": "Patient Defense", "t": "bonus", "u": 0, "r": "", "d": "Take the Disengage action as a Bonus Action. Spend 1 Focus Point to take both Disengage and Dodge as a Bonus Action."}, {"n": "Step of the Wind", "t": "bonus", "u": 0, "r": "", "d": "Take the Dash action as a Bonus Action. Spend 1 Focus Point to take both Disengage and Dash as a Bonus Action, and your jump distance doubles for the turn."}, {"n": "Uncanny Metabolism", "t": "other", "u": 1, "r": "LR", "d": "Once per Long Rest, when you roll Initiative you can regain all expended Focus Points and regain a Martial Arts die + level HP."}, {"n": "Deflect Attack", "t": "reaction", "u": 0, "r": "", "d": "When an attack with Bludgeoning, Piercing, or Slashing damage hits you, reduce the attack’s total damage by 1d10 + Dex mod + level."}, {"n": "Deflect Attack: Redirect Attack", "t": "reaction", "u": 0, "r": "", "d": "If Deflect Attack reduces the damage to 0, spend 1 Focus Point to redirect the force at a creature within 5 ft (60 ft if ranged)."}, {"n": "Slow Fall", "t": "reaction", "u": 0, "r": "", "d": "When you fall, reduce any falling damage by 5 × level."}, {"n": "Stunning Strike", "t": "action", "u": 0, "r": "", "d": "Once per turn, when you hit with a Monk weapon or Unarmed Strike, spend 1 Focus Point: the target makes a Con save against your Wis save DC or is Stunned."}, {"n": "Empowered Strikes", "t": "other", "u": 0, "r": "", "d": "Your Unarmed Strikes can deal Force damage or their normal damage type."}, {"n": "Step of the Wind (Heightened)", "t": "bonus", "u": 0, "r": "", "d": "When you spend a Focus Point on Step of the Wind, you can carry a willing Large or smaller creature within 5 ft along with you without provoking Opportunity Attacks."}, {"n": "Patient Defense (Heightened)", "t": "bonus", "u": 0, "r": "", "d": "When you spend a Focus Point on Patient Defense, you also gain Temp HP (two Martial Arts dice)."}, {"n": "Flurry of Blows (Heightened)", "t": "bonus", "u": 0, "r": "", "d": "Flurry of Blows makes three Unarmed Strikes instead of two."}, {"n": "Flurry of Blows: Addle", "t": "bonus", "u": 0, "r": "", "d": "A creature hit by Flurry of Blows can’t make Opportunity Attacks until the start of its next turn."}, {"n": "Flurry of Blows: Push", "t": "bonus", "u": 0, "r": "", "d": "A creature hit by Flurry of Blows makes a Str save against your Wis save DC or is pushed 15 ft away."}, {"n": "Flurry of Blows: Topple", "t": "bonus", "u": 0, "r": "", "d": "A creature hit by Flurry of Blows makes a Dex save against your Wis save DC or falls Prone."}, {"n": "Wholeness of Body", "t": "bonus", "u": 0, "r": "LR", "d": "Heal yourself for a Martial Arts die + Wis mod HP. Uses equal to your Wis mod per Long Rest."}, {"n": "Step of the Wind: Fleet Step", "t": "bonus", "u": 0, "r": "", "d": "When you take a Bonus Action other than Step of the Wind, you can use Step of the Wind immediately after."}], "spells": [], "weapons": []}}$dnd$::jsonb, updated_at = now() where id = 'coach' and kind = 'char';
update public.docs set data = data || $dnd${"dnd": {"pb": 4, "skills": {"acrobatics": 0, "animal-handling": 0, "arcana": 0, "athletics": 0, "deception": 1, "history": 0, "insight": 2, "intimidation": 1, "investigation": 0, "medicine": 0, "nature": 0, "perception": 1, "performance": 2, "persuasion": 2, "religion": 0, "sleight-of-hand": 2, "stealth": 0, "survival": 0}, "adv": [], "half": true, "profs": ["Zulkoon", "Fiddle", "Drum", "Simple Weapons", "Light Armor"], "langs": ["Common", "Elvish", "Orc"], "senses": ["Darkvision 60 ft"], "speed": {"walk": 30, "bonus": 0}, "acts": [{"n": "Bardic Inspiration", "t": "bonus", "u": 0, "r": "SR", "d": "As a Bonus Action, inspire a creature within 60 ft that can see or hear you. Once within the next hour, when it fails a D20 Test, it adds your Bardic Inspiration die."}, {"n": "Regain Bardic Inspiration", "t": "other", "u": 0, "r": "", "d": "Expend a spell slot (no action required) to regain one use of Bardic Inspiration."}, {"n": "Countercharm", "t": "reaction", "u": 0, "r": "", "d": "If you or a creature within 30 ft fails a save against Charmed or Frightened, it can reroll the save with Advantage."}, {"n": "Cutting Words", "t": "reaction", "u": 0, "r": "", "d": "When a creature you can see within 60 ft makes a damage roll or succeeds on an ability check or attack roll, spend a Bardic Inspiration and subtract the die from the roll."}, {"n": "Initiate a Circle Spell", "t": "action", "u": 0, "r": "", "d": "Take a Magic action to begin a Circle spell, choosing a Circle casting option."}, {"n": "Circle Spell: Augment", "t": "other", "u": 0, "r": "", "d": "Increase a spell’s range by 1,000 ft per secondary caster, up to 1 mile."}, {"n": "Circle Spell: Distribute", "t": "other", "u": 0, "r": "", "d": "Share Concentration on the spell among you and the secondary casters."}, {"n": "Circle Spell: Expand", "t": "other", "u": 0, "r": "", "d": "Increase one dimension of the spell’s area by 10 ft per secondary caster."}, {"n": "Circle Spell: Prolong", "t": "other", "u": 0, "r": "", "d": "Lengthen a spell of 1 minute or longer based on the number of secondary casters."}, {"n": "Circle Spell: Safeguard", "t": "other", "u": 0, "r": "", "d": "Carve out a safe zone of 5-ft cubes inside the spell’s area."}, {"n": "Circle Spell: Supplant", "t": "other", "u": 0, "r": "", "d": "Reduce a consumed material component’s cost by 50 gp per secondary caster."}], "spells": [{"n": "Vicious Mockery", "l": 0, "t": "action", "c": false, "r": "60 ft"}, {"n": "Spare the Dying", "l": 0, "t": "action", "c": false, "r": "15 ft"}, {"n": "Acid Splash", "l": 0, "t": "action", "c": false, "r": "60 ft"}, {"n": "Frostbite", "l": 0, "t": "action", "c": false, "r": "60 ft"}, {"n": "Prestidigitation", "l": 0, "t": "action", "c": false, "r": "10 ft"}, {"n": "Sacred Flame", "l": 0, "t": "action", "c": false, "r": "60 ft"}, {"n": "Cure Wounds", "l": 1, "t": "action", "c": false, "r": "Touch"}, {"n": "Charm Person", "l": 1, "t": "action", "c": false, "r": "30 ft"}, {"n": "Magic Missile", "l": 1, "t": "action", "c": false, "r": "120 ft"}, {"n": "Detect Magic", "l": 1, "t": "action", "c": true, "r": "Self"}, {"n": "Barkskin", "l": 2, "t": "bonus", "c": false, "r": "Touch"}, {"n": "Find Traps", "l": 2, "t": "action", "c": false, "r": "120 ft"}, {"n": "Invisibility", "l": 2, "t": "action", "c": true, "r": "Touch"}, {"n": "Misty Step", "l": 2, "t": "bonus", "c": false, "r": "Self"}, {"n": "Mass Healing Word", "l": 3, "t": "bonus", "c": false, "r": "60 ft"}, {"n": "Lightning Bolt", "l": 3, "t": "action", "c": false, "r": "Self"}, {"n": "Speak with Dead", "l": 3, "t": "action", "c": false, "r": "10 ft"}, {"n": "Vampiric Touch", "l": 3, "t": "action", "c": true, "r": "Self"}, {"n": "Vitriolic Sphere", "l": 4, "t": "action", "c": false, "r": "150 ft"}, {"n": "Blight", "l": 4, "t": "action", "c": false, "r": "30 ft"}, {"n": "Dispel Evil and Good", "l": 5, "t": "action", "c": true, "r": "Self"}, {"n": "Flame Strike", "l": 5, "t": "action", "c": false, "r": "60 ft"}, {"n": "Seeming", "l": 5, "t": "action", "c": false, "r": "30 ft"}, {"n": "Summon Dragon", "l": 5, "t": "action", "c": true, "r": "60 ft"}], "weapons": [{"n": "Dagger", "eq": true, "dmg": "1d4", "dt": "Piercing", "props": "Finesse, Light, Thrown, Nick", "range": "20/60"}]}}$dnd$::jsonb, updated_at = now() where id = 'cramaris' and kind = 'char';
