update public.docs set data = data || $dnd${"dnd": {"pb": 4, "skills": {"acrobatics": 0, "animal-handling": 0, "arcana": 0, "athletics": 1, "deception": 0, "history": 0, "insight": 1, "intimidation": 1, "investigation": 0, "medicine": 0, "nature": 0, "perception": 0, "performance": 0, "persuasion": 1, "religion": 0, "sleight-of-hand": 0, "stealth": 1, "survival": 0}, "adv": ["athletics"], "half": false, "profs": ["Simple Weapons", "Martial Weapons", "Light Armor", "Medium Armor", "Shields", "Heavy Armor"], "langs": ["Common", "Elvish", "Dwarvish"], "senses": ["Darkvision 120 ft"], "speed": {"walk": 30, "bonus": 0}, "acts": [{"n": "Adrenaline Rush", "t": "bonus", "u": 4, "r": "SR", "d": "As a Bonus Action, take the Dash action and gain Temp HP equal to your proficiency bonus. Uses equal to your proficiency bonus per Short or Long Rest."}, {"n": "Relentless Endurance", "t": "other", "u": 1, "r": "LR", "d": "Once per Long Rest, when you drop to 0 HP but aren’t killed outright, drop to 1 HP instead."}, {"n": "Second Wind", "t": "bonus", "u": 4, "r": "LR", "d": "Regain 1d10 + level HP. Regain one use on a Short Rest, all on a Long Rest."}, {"n": "Action Surge", "t": "other", "u": 1, "r": "SR", "d": "On your turn, take one additional action (not the Magic action). Once per Short or Long Rest."}, {"n": "Tactical Mind", "t": "other", "u": 0, "r": "", "d": "When you fail an ability check, spend a Second Wind to add 1d10 to it. If it still fails, the use isn’t spent."}, {"n": "Second Wind: Tactical Shift", "t": "bonus", "u": 0, "r": "", "d": "When you use Second Wind as a Bonus Action, move up to half your Speed without provoking Opportunity Attacks."}, {"n": "Indomitable", "t": "other", "u": 1, "r": "LR", "d": "Reroll a failed save with a bonus equal to your Fighter level. Once per Long Rest."}, {"n": "Tactical Master", "t": "action", "u": 0, "r": "", "d": "When you attack with a weapon whose mastery you can use, swap its mastery for Push, Sap, or Slow."}, {"n": "Tactical Master: Push", "t": "action", "u": 0, "r": "", "d": "On a hit, push a Large or smaller creature up to 10 ft straight away."}, {"n": "Tactical Master: Sap", "t": "action", "u": 0, "r": "", "d": "On a hit, the creature has Disadvantage on its next attack roll before your next turn."}, {"n": "Tactical Master: Slow", "t": "action", "u": 0, "r": "", "d": "On a hit that deals damage, reduce its Speed by 10 ft until your next turn."}, {"n": "Improved Critical", "t": "other", "u": 0, "r": "", "d": "Your weapon attacks and Unarmed Strikes crit on a 19 or 20."}, {"n": "Heroic Warrior", "t": "other", "u": 0, "r": "", "d": "In combat, give yourself Heroic Inspiration whenever you start your turn without it."}, {"n": "Graze (Greatsword)", "t": "action", "u": 0, "r": "", "d": "If a Greatsword attack misses, deal damage equal to the ability modifier you used."}, {"n": "Push (Warhammer)", "t": "action", "u": 0, "r": "", "d": "On a Warhammer hit, push a Large or smaller creature up to 10 ft away."}, {"n": "Topple (Battleaxe)", "t": "action", "u": 0, "r": "", "d": "On a Battleaxe hit, the target makes a Con save (DC 8 + prof + ability mod) or falls Prone."}], "spells": [], "weapons": [{"n": "Javelin", "eq": true, "dmg": "1d6", "dt": "Piercing", "props": "Thrown, Slow", "range": "30/120"}, {"n": "Flail", "eq": true, "dmg": "1d8", "dt": "Bludgeoning", "props": "Sap", "range": "5"}, {"n": "Greatsword", "eq": true, "dmg": "2d6", "dt": "Slashing", "props": "Heavy, Two-Handed, Graze", "range": "5"}, {"n": "Warhammer", "eq": false, "dmg": "1d8", "dt": "Bludgeoning", "props": "Versatile, Push", "range": "5"}]}}$dnd$::jsonb, updated_at = now() where id = 'gorc' and kind = 'char';
update public.docs set data = data || $dnd${"dnd": {"pb": 4, "skills": {"acrobatics": 0, "animal-handling": 0, "arcana": 0, "athletics": 1, "deception": 0, "history": 0, "insight": 0, "intimidation": 1, "investigation": 0, "medicine": 1, "nature": 0, "perception": 0, "performance": 0, "persuasion": 0, "religion": 0, "sleight-of-hand": 0, "stealth": 0, "survival": 1}, "adv": [], "half": false, "profs": ["Battleaxe", "Handaxe", "Light Hammer", "Warhammer", "Smith's Tools", "Light Armor", "Medium Armor", "Woodcarver's Tools", "Heavy Armor", "Shields", "Simple Weapons", "Martial Weapons", "Dice Set", "Vehicles (Land)"], "langs": ["Common", "Dwarvish"], "senses": ["Darkvision 60 ft"], "speed": {"walk": 25, "bonus": 0}, "acts": [{"n": "Extra Attack", "t": "action", "u": 0, "r": "", "d": "You attack three times whenever you take the Attack action on your turn."}, {"n": "Second Wind", "t": "bonus", "u": 1, "r": "SR", "d": "Once per Short Rest, use a Bonus Action to regain 1d10 + level HP."}, {"n": "Action Surge", "t": "other", "u": 1, "r": "SR", "d": "Take one additional action on your turn. Once per Short Rest."}, {"n": "Indomitable", "t": "other", "u": 1, "r": "LR", "d": "Reroll a failed save; you must use the new roll. Once per Long Rest."}, {"n": "Superiority Dice", "t": "other", "u": 5, "r": "SR", "d": "Five superiority dice fuel your maneuvers. You regain them on a Short Rest."}, {"n": "Maneuvers: Parry", "t": "reaction", "u": 0, "r": "", "d": "When a creature damages you with a melee attack, spend a superiority die to reduce the damage by the roll + Dex mod."}, {"n": "Maneuvers: Riposte", "t": "reaction", "u": 0, "r": "", "d": "When a creature misses you with a melee attack, spend a superiority die to make a melee attack against it, adding the die to damage."}, {"n": "Maneuvers: Trip Attack", "t": "action", "u": 0, "r": "", "d": "On a hit, spend a superiority die to add it to damage; a Large or smaller target makes a Str save or falls Prone."}, {"n": "Maneuvers: Disarming Attack", "t": "action", "u": 0, "r": "", "d": "On a hit, spend a superiority die to add it to damage; the target makes a Str save or drops an item it holds."}, {"n": "Maneuvers: Goading Attack", "t": "action", "u": 0, "r": "", "d": "On a hit, spend a superiority die to add it to damage; the target makes a Wis save or has Disadvantage on attacks against anyone but you."}, {"n": "Maneuvers: Maneuvering Attack", "t": "action", "u": 0, "r": "", "d": "On a hit, spend a superiority die to add it to damage; an ally can use its reaction to move half its speed without provoking."}, {"n": "Maneuvers: Evasive Footwork", "t": "move", "u": 0, "r": "", "d": "When you move, spend a superiority die and add the roll to your AC until you stop moving."}, {"n": "Know Your Enemy", "t": "other", "u": 0, "r": "", "d": "After observing a creature for 1 minute outside combat, learn how it compares to you in scores, AC, HP, or level."}, {"n": "Sentinel Attack", "t": "reaction", "u": 0, "r": "", "d": "When a creature within 5 ft attacks a target other than you, make a melee weapon attack against it."}, {"n": "Shield Master Shove", "t": "bonus", "u": 0, "r": "", "d": "If you take the Attack action, use a Bonus Action to shove a creature within 5 ft with your shield."}, {"n": "Shield Master Evasion", "t": "reaction", "u": 0, "r": "", "d": "If an effect lets you save for half damage, take no damage on a success."}], "spells": [], "weapons": [{"n": "Handaxe", "eq": true, "dmg": "1d6", "dt": "Slashing", "props": "Light, Thrown, Vex", "range": "20/60"}, {"n": "Shortbow", "eq": true, "dmg": "1d6", "dt": "Piercing", "props": "Ammunition, Two-Handed, Vex", "range": "80/320"}, {"n": "Battleaxe", "eq": true, "dmg": "1d8", "dt": "Slashing", "props": "Versatile, Topple", "range": "5"}, {"n": "Greataxe", "eq": true, "dmg": "1d12", "dt": "Slashing", "props": "Heavy, Two-Handed, Cleave", "range": "5"}, {"n": "Warhammer", "eq": true, "dmg": "1d8", "dt": "Bludgeoning", "props": "Versatile, Push", "range"